window.kbPageData["views/entry/k-9c44a126f0b73503"] = {"key":"entry/k-9c44a126f0b73503","state":{"route":"entry/k-9c44a126f0b73503"},"node":{"id":"k-9c44a126f0b73503","mode":"k","title":"党的建设面临的突出问题","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"5.党的建设面临的突出问题\n在十八届中央政治局常委同中外记者见面时，习近平总书记斩钉截铁地指出“坚持\n党要管党、从严治党，切实解决自身存在的突出问题”，彰显了大党大国领袖深邃的历\n史洞察和鲜明的问题导向。从当时党内实际状况来看，一些长期存在的深层次问题尚未\n根本解决，一些新问题又日益凸显。\n有的地方…","sources":[{"id":"7a3d4d37e3aac5f1","label":"党的建设面临的突出问题","topic":"党政制度与理论","category":"非时政","text":"5.党的建设面临的突出问题\n在十八届中央政治局常委同中外记者见面时，习近平总书记斩钉截铁地指出“坚持\n党要管党、从严治党，切实解决自身存在的突出问题”，彰显了大党大国领袖深邃的历\n史洞察和鲜明的问题导向。从当时党内实际状况来看，一些长期存在的深层次问题尚未\n根本解决，一些新问题又日益凸显。\n有的地方和部门对坚持党的领导认识模糊、行动乏力，落实党的领导弱化虚化淡\n化、党的建设缺失；\n一些基层党组织软弱涣散，一些党员、干部党性意识不强，政治信仰发生动摇，形\n式主义、官僚主义、享乐主义和奢靡之风盛行，特权思想和特权现象较为严重；\n选人用人风气不正，任人唯亲、跑官要官、买官卖官、拉票贿选现象屡禁不止；\n一些党员、干部法治意识、纪律观念淡薄，自我约束松懈，纪律执行失之于宽、失\n之于松、失之于软；\n贪污受贿、腐化堕落等现象滋生蔓延，一些领导干部特别是高级干部贪腐程度相当\n严重甚至触目惊心；等等。\n这些问题具有极强的危险性和破坏性，严重损害党的形象和威信、侵蚀党的执政根\n基，令党和人民忧心忡忡。\n——共产党员网","source":{"doc":"41195a191a57c1c36332","first":9,"last":10,"page":9,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-9c44a126f0b73503":[]}};
